func TestRecoverableRetryReplaysFromTheClaimedRow(t *testing.T) {
	prod := &recordingProducer{}
	s := &SagaCoordinator{producer: prod, logger: zap.NewNop(), db: unreachableDB(t)}
	claimed := claimedRowFixture(t, requestID, true) // payload-bearing, as the claim returns it
	inMemory := *claimed
	inMemory.RequestPayload = nil // what any DB-loaded state carries (json:"-")
	state := &OrchestrationState{..., AwaitedRequests: map[string]*AwaitedRequest{requestID: &inMemory}}
	if err := s.handleRecoverableError(ctx, state, requestID, execCtx, recoverableResponseFixture(), claimed); err != nil { t.Fatalf(...) }
	// exactly 1 replay on system.agent.reasoning-agent.requests; decodes as RequestMessage;
	// msg.Headers.OrchestrationID == "child-orch-216" (never the parent's); RetryVersion == 1
}
